**model.js additions** (pure, ~35 lines):

```js
// B-5 compare tray pure contracts...
export function alignCompareRows(left, right) {
  const maxHops = Math.max(left.hops, right.hops);
  const rows = [];
  for (let n = 1; n <= maxHops; n += 1) {
    rows.push({ n, left: left.entries[n - 1]?.text ?? '—', right: right.entries[n - 1]?.text ?? '—' });
  }
  return rows;
}
```

Wait: entries are journey-log entry objects `{ label, text, run, hop }`. Run shape: `{ run: id, hops: n, label: 'GET /about', entries: [...] }` hop-ascending. `entries[n-1]` is hop n if hop-ascending and contiguous. But safer to key by hop: find entry with hop === n. Use `left.entries.find((e) => e.hop === n)?.text ?? '—'`. hop values for trace runs are 1..finalHop (from addToJourney `hop: snapshot.trace.hop`). Crowd ticks have hop: 0. So find by hop is robust.

`nextCompareSlots(slots, newRun)`:

```js
export function nextCompareSlots(slots, newRun) {
  const { a = null, b = null } = slots ?? {};
  // Trace-runs-only: a run without at least 2 hop entries is not comparable.
  if (!newRun || !Number.isInteger(newRun.hops) || newRun.hops < 2 || !newRun.entries?.length) {
    return { a, b, changed: false };
  }
  if (a && a.run === newRun.run) return { a, b, changed: false };
  if (b && b.run === newRun.run) return { a, b, changed: false };
  if (!a) return { a: newRun, b, changed: true };
  if (!b) return { a, b: newRun, changed: true };
  return { a: b, b: newRun, changed: true };
}
```

