export function nextCompareSlots(slots, newRun) {
  const current = { a: slots?.a ?? null, b: slots?.b ?? null };
  const comparable =
    newRun && Number.isInteger(newRun.hops) && newRun.hops >= 2 &&
    Array.isArray(newRun.entries) && newRun.entries.length > 0;
  if (!comparable || current.a?.run === newRun.run || current.b?.run === newRun.run) {
    return { ...current, changed: false };
  }
  if (!current.a) return { a: newRun, b: current.b, changed: true };
  if (!current.b) return { a: current.a, b: newRun, changed: true };
  return { a: current.b, b: newRun, changed: true };
}
```

