```js
// B-5: hop-aligned compare rows over max(left.hops, right.hops); the
// exhausted side renders the em-dash. Entries are matched by hop index and
// the texts pass through verbatim — this function never mutates or rewrites
// them (PINS: compare renders the journey log's own frames, DL-1/DL-3).
export function alignCompareRows(left, right) {
  const total = Math.max(left?.hops ?? 0, right?.hops ?? 0);
  return Array.from({ length: total }, (_, i) => {
    const n = i + 1;
    return {
      n,
      left: left?.entries?.find((e) => e.hop === n)?.text ?? '—',
      right: right?.entries?.find((e) => e.hop === n)?.text ?? '—',
    };
  });
}
