27: // Extract comment paragraphs [{ line, text }] while skipping '', "", and ``
28: // string literals (so template code in inspector-source.js and test titles
29: // in it('...') are not misread as comments).
30: function extractCommentParagraphs(src) {
31:   const blocks = [];
32:   let i = 0;
33:   let line = 1;
34:   while (i < src.length) {
35:     const ch = src[i];
36:     const next = src[i + 1];
37:     if (ch === '\n') {
38:       line += 1;
39:       i += 1;
40:     } else if (ch === "'" || ch === '"' || ch === '`') {
41:       const quote = ch;
42:       i += 1;
43:       while (i < src.length && src[i] !== quote) {
44:         if (src[i] === '\\') i += 1;
45:         if (src[i] === '\n') line += 1;
46:         i += 1;
47:       }
48:       i += 1;
49:     } else if (ch === '/' && next === '/') {
50:       const startLine = line;
51:       const end = src.indexOf('\n', i);
52:       const raw = (end === -1 ? src.slice(i + 2) : src.slice(i + 2, end)).trim();
53:       blocks.push({ kind: 'line', line: startLine, text: raw });
54:       i = end === -1 ? src.length : end;
55:     } else if (ch === '/' && next === '*') {
56:       const startLine = line;
57:       const end = src.indexOf('*/', i + 2);
58:       const raw = end === -1 ? src.slice(i + 2) : src.slice(i + 2, end);
59:       line += raw.split('\n').length - 1;
60:       blocks.push({ kind: 'block', line: startLine, text: raw.trim() });
61:       i = end === -1 ? src.length : end + 2;
62:     } else {
63:       i += 1;
64:     }
65:   }
66: 
67:   // Merge adjacent non-empty `//` lines into paragraphs; blank `//` or a new
68:   // leading claim keyword starts a fresh paragraph.
69:   const paragraphs = [];
70:   let current = null;
71:   for (const b of blocks) {
72:     if (b.kind === 'block') {
73:       if (current) paragraphs.push(current);
74:       current = null;
75:       if (b.text) paragraphs.push({ line: b.line, text: b.text });
76:     } else if (b.text === '') {
